static const wchar_t* TARGET_PROCESS = L"TargetGame.exe";
static const char*    CLIENT_MODULE  = "client.dll";

// 模块内偏移（用 CE / ReClass / IDA 实测替换）
static const DWORD OFF_ENTITY_LIST  = 0x01A2B3C4; // dwEntityList
static const DWORD OFF_LOCAL_PLAYER = 0x01A2B3C8; // dwLocalPlayer
static const DWORD OFF_VIEW_MATRIX  = 0x01A2B400; // dwViewMatrix (float[16])
static const DWORD OFF_ENTITY_SIZE  = 0x10;       // 实体表指针步长（4字节=8/8字节=0x10）

// 实体内部偏移
