static const DWORD OFF_HEALTH     = 0x100;  // int
static const DWORD OFF_DORMANT    = 0x0ED;  // bool
static const DWORD OFF_POS        = 0x138;  // Vec3 origin
static const DWORD OFF_VIEWOFFSET = 0x108;  // Vec3 眼睛高度
