struct Vec3 { float x, y, z; };
struct Vec2 { float x, y; };

static HANDLE    g_proc   = nullptr;
static uintptr_t g_client = 0;

// ---------------- 进程 / 模块定位 ----------------
DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

uintptr_t GetModuleBase(DWORD pid, const char* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    wchar_t wmod[256]{};
    MultiByteToWideChar(CP_ACP, 0, mod, -1, wmod, 256);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, wmod)) { base = (uintptr_t)me.modBaseAddr; break; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

// ---------------- 读内存包装 ----------------
template <typename T>
bool Read(uintptr_t addr, T& out) {
    SIZE_T n = 0;
    return ReadProcessMemory(g_proc, (LPCVOID)addr, &out, sizeof(T), &n) && n == sizeof(T);
}

// 批量读：一帧多次 RPM 太慢，一次读整个实体结构到本地 buffer 再取字段
bool ReadBlock(uintptr_t addr, void* buf, size_t size) {
    SIZE_T n = 0;
    return ReadProcessMemory(g_proc, (LPCVOID)addr, buf, size, &n) && n == size;
}

// ---------------- 世界坐标 -> 屏幕坐标 ----------------
// vmLayout: 0 = 行主序(column-vector, D3D 常见), 1 = 列主序
bool WorldToScreen(const Vec3& p, Vec2& out, const float m[16], int w, int h, int vmLayout = 0) {
    auto at = [&](int r, int c) { return vmLayout ? m[c * 4 + r] : m[r * 4 + c]; };
    float cx = p.x * at(0,0) + p.y * at(0,1) + p.z * at(0,2) + at(0,3);
    float cy = p.x * at(1,0) + p.y * at(1,1) + p.z * at(1,2) + at(1,3);
    float cw = p.x * at(3,0) + p.y * at(3,1) + p.z * at(3,2) + at(3,3);
    if (cw < 0.001f) return false;                 // 在相机背后
    float ndcX = cx / cw, ndcY = cy / cw;
    out.x = (w * 0.5f) * (1.0f + ndcX);
    out.y = (h * 0.5f) * (1.0f - ndcY);
    return true;
}

